public sealed record SearchHit(string Id, string Title, double Score);

public interface ISearchFanOut
{
    Task<IReadOnlyList<SearchHit>> SearchAsync(string query, CancellationToken ct);
}

public sealed class SearchFanOut(IReadOnlyList<ISearchBackend> backends, int maxParallel) : ISearchFanOut
{
    public async Task<IReadOnlyList<SearchHit>> SearchAsync(string query, CancellationToken ct)
    {
        using var gate = new SemaphoreSlim(maxParallel, maxParallel);
        var tasks = backends.Select(b => SearchBackendAsync(b, query, gate, ct)).ToArray();
        var batches = await Task.WhenAll(tasks).ConfigureAwait(false);
        var bestById = new Dictionary<string, SearchHit>();
        foreach (var hit in batches.SelectMany(x => x))
        {
            if (!bestById.TryGetValue(hit.Id, out var existing) || hit.Score > existing.Score)
                bestById[hit.Id] = hit;
        }
        return bestById.Values.OrderByDescending(h => h.Score).ThenBy(h => h.Id).ToList();
    }

    private static async Task<IReadOnlyList<SearchHit>> SearchBackendAsync(
        ISearchBackend backend, string query, SemaphoreSlim gate, CancellationToken ct)
    {
        await gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            return await backend.SearchAsync(query, ct).ConfigureAwait(false);
        }
        finally { gate.Release(); }
    }
}

public interface ISearchBackend
{
    Task<IReadOnlyList<SearchHit>> SearchAsync(string query, CancellationToken ct);
}
